"""Accuracy/latency/token-usage benchmark across providers and models.

Runs the three tasks in tasks.py against every (provider, model) pair in
MODELS, scores each task's output against hand-verified ground truth (derived
from the existing samples/*_mapped.csv, *_categorized.csv, and
*_matched.csv, which were generated by a prior TypeSafe run), and prints a
per-task and per-model summary of accuracy, elapsed time, and token usage.

Usage:
    python eval.py
"""

import time

import pandas as pd
from dotenv import load_dotenv

from providers import get_provider
from tasks import classify_categories, lookup_match, match_sales_columns

# (label, provider name, model) to benchmark. model=None uses the provider's
# default. Add "anthropic"/"gemini" entries here once ANTHROPIC_API_KEY /
# GEMINI_API_KEY are set in .env.
MODELS = [
    ("typesafe", "typesafe", None),
    ("gemini:gemini-3.5-flash-lite", "gemini", "gemini-3.5-flash-lite"),
    ("ollama:qwen3:0.6b", "ollama", "qwen3:0.6b"),
    ("ollama:qwen3:4b", "ollama", "qwen3:4b"),
    ("ollama:qwen3:8b", "ollama", "qwen3:8b"),
]

SALES_CSV = "samples/sales.csv"
SALES_EXPECTED = {"item_id": "product_code", "sales_qty": "qty", "sales_date": "txn_date"}

ITEMS_CSV = "samples/items.csv"
CATEGORY_EXPECTED = {
    "Sofa": "furniture",
    "Pickup Truck": "vehicles",
    "Carrot": "vegetables",
    "Laptop": "electronics",
}

LOOKUP_SOURCE_CSV = "samples/lookup_source.csv"
LOOKUP_CANDIDATES_CSV = "samples/lookup_candidates.csv"
LOOKUP_EXPECTED = {
    "MacBook Pro": "MacBook Pro 14-inch",
    "Sofa Bed": "Sofa",
    "Carrots": "Carrot",
    "e-bike": "Electric Bicycle",
}


def _score(predicted: dict, expected: dict) -> tuple[int, int]:
    """Return (correct, total) exact-match counts against expected."""
    correct = sum(1 for key, want in expected.items() if predicted.get(key) == want)
    return correct, len(expected)


def run_task(name: str, fn, expected: dict, provider) -> dict:
    """Run one task fn() (already bound to `provider`), timing it and taking
    a before/after token-usage delta off the provider's running total."""
    start_in, start_out = provider.usage.input_tokens, provider.usage.output_tokens
    start = time.perf_counter()
    predicted = fn()
    elapsed = time.perf_counter() - start
    correct, total = _score(predicted, expected)
    return {
        "task": name,
        "elapsed": elapsed,
        "correct": correct,
        "total": total,
        "input_tokens": provider.usage.input_tokens - start_in,
        "output_tokens": provider.usage.output_tokens - start_out,
    }


def print_row(model: str, row: dict) -> None:
    acc = f"{row['correct']}/{row['total']}"
    print(
        f"  {row['task']:<18}{acc:<8}{row['elapsed']:>8.2f}s"
        f"{row['input_tokens']:>10} in{row['output_tokens']:>8} out"
    )


def print_summary(results: list[dict]) -> None:
    totals: dict[str, dict] = {}
    for r in results:
        t = totals.setdefault(r["model"], {"correct": 0, "total": 0, "elapsed": 0.0, "in": 0, "out": 0})
        t["correct"] += r["correct"]
        t["total"] += r["total"]
        t["elapsed"] += r["elapsed"]
        t["in"] += r["input_tokens"]
        t["out"] += r["output_tokens"]

    print("\n=== Summary ===")
    header = f"{'model':<20}{'accuracy':<12}{'time(s)':>10}{'tokens in':>12}{'tokens out':>12}"
    print(header)
    print("-" * len(header))
    for model, t in totals.items():
        acc = f"{t['correct']}/{t['total']}"
        print(f"{model:<20}{acc:<12}{t['elapsed']:>10.2f}{t['in']:>12}{t['out']:>12}")


def main() -> None:
    load_dotenv()

    sales_df = pd.read_csv(SALES_CSV)
    items = pd.read_csv(ITEMS_CSV)["item_name"].tolist()
    lookup_values = pd.read_csv(LOOKUP_SOURCE_CSV)["item"].tolist()
    lookup_candidates = pd.read_csv(LOOKUP_CANDIDATES_CSV)["name"].tolist()

    results = []
    for label, provider_name, model in MODELS:
        print(f"\n{label}")
        try:
            provider = get_provider(provider_name, model)
            rows = [
                run_task(
                    "map-sales",
                    lambda: match_sales_columns(sales_df, provider=provider),
                    SALES_EXPECTED,
                    provider,
                ),
                run_task(
                    "classify-category",
                    lambda: classify_categories(items, provider=provider),
                    CATEGORY_EXPECTED,
                    provider,
                ),
                run_task(
                    "lookup-match",
                    lambda: lookup_match(lookup_values, lookup_candidates, provider=provider),
                    LOOKUP_EXPECTED,
                    provider,
                ),
            ]
        except Exception as exc:  # noqa: BLE001 - keep benchmarking the rest on one model's failure
            print(f"  FAILED: {exc}")
            continue
        for row in rows:
            print_row(label, row)
            row["model"] = label
            results.append(row)

    print_summary(results)


if __name__ == "__main__":
    main()
